var n=`0943-tempura`;var a=`world-0943`;var s=`JP`;var t=`east-asia`;var r=4;var o=43;var l={en:`Tempura`,ua:`Темпура`};var d={en:`Tempura is a Japan dish made with shrimp, kabocha squash, green beans, all-purpose flour. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Темпура, страва кухні країни Японія. Основні складники: креветка, гарбуз кабоча, стручкова квасоля, пшеничне борошно універсальне. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var m=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:12,i:[[`shrimp`,580,`g`],[`kabocha-squash`,300,`g`],[`green-beans`,250,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:7,i:[[`all-purpose-flour`,210,`g`],[`cornstarch`,65,`g`],[`ice-cubes`,120,`g`],[`water`,240,`ml`],[`chicken-egg`,1,`pcs`]]},{en:`Keep tempura batter ice-cold and lightly mixed; fry coated shrimp and vegetables in hot oil until crisp and fully cooked.`,ua:`Тримайте тісто темпури дуже холодним і ледь перемішаним; смажте креветки та овочі в гарячій олії до хрусткості й готовності.`,t:[`tempura-frying`],m:16,i:[[`canola-oil`,800,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`dashi-stock`,250,`ml`],[`mirin`,50,`ml`],[`light-soy-sauce`,60,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`daikon`,150,`g`]]}];var g={slug:n,id:a,country:`JP`,region:t,servings:4,minutes:43,title:l,text:d,steps:m};export{s as country,g as default,a as id,o as minutes,t as region,r as servings,n as slug,m as steps,d as text,l as title};